for name in ['D5','Problems']:
 p=H/f'omega-{name}-tree.json';t=json.loads(p.read_text());r['trees']['omega-'+name]={'sha':t['sha'],'truncated':t.get('truncated'),'paths':len(t['tree'])}
 for i,x in r['by_id'].items():
  for z in t['tree']:
   ms=[s for s in x['terms'] if s.lower() in z['path'].lower()]
   if ms:x['hits'].append({'file':p.name,'path':z['path'],'terms':ms})
r['repository_searches'].append({'file':'github-search-potts.json','total_count':json.loads((H/'github-search-potts.json').read_text()).get('total_count')})
r['limitation']='Raw current candidate indexes and complete Lean Pool paths screened. Omega D5/Problems complete subtrees screened; root recursive response was truncated. GitHub API repository queries cover only leading computational routes. Not global novelty clearance.'
